<x-admin-layout title="Homepage builder"><p class="notice">Enable, order and edit the supported homepage sections below. Lower positions appear first. Stock-photo previews remain labeled; use authentic photography for actual products. Testimonials use approved, verified customer reviews only.</p><a class="button button-light" href="/">Preview live homepage ↗</a>@foreach($sections as $section)<details class="builder-section"><summary><span class="status">{{ $section->published?'Enabled':'Hidden' }}</span> {{ ucwords(str_replace('_',' ',$section->kind)) }} <small>Position {{ $section->position }}</small><span class="text-link">Edit section</span></summary><form method="post" action="/admin/homepage/{{ $section->id }}" enctype="multipart/form-data">@csrf<div class="form-grid">@if($section->kind!=='benefits')<label>Section title / hero first line<input name="title" value="{{ $section->title }}" maxlength="180"></label>@endif<label>Position<input type="number" name="position" value="{{ $section->position }}" min="0" max="1000" required></label>@if(in_array($section->kind,['hero','brand','campaign','faq']))<label>Call-to-action label<input name="link_label" value="{{ $section->link_label }}" maxlength="60"></label><label>Call-to-action destination<input name="link_path" value="{{ $section->link_path }}" maxlength="200" placeholder="/shop"></label>@endif @if(in_array($section->kind,['hero','campaign']))<label>Desktop image<input type="file" name="image_upload" accept="image/jpeg,image/png,image/webp"></label><label>Mobile image<input type="file" name="mobile_upload" accept="image/jpeg,image/png,image/webp"></label><label>Image alt text<input name="image_alt" value="{{ $section->image_alt }}" maxlength="200"></label>@endif</div>@if(in_array($section->kind,['hero','brand','campaign','faq']))<label>Supporting text<textarea name="content" maxlength="4000">{{ $section->content }}</textarea></label>@endif<div class="image-editor">@foreach(['image'=>'Desktop','mobile_image'=>'Mobile'] as $key=>$label)@if($section->$key)<div><img src="{{ Storage::url($section->$key) }}" alt="{{ $label }} section image" width="180"><label class="check"><input type="checkbox" name="{{ $key==='image'?'remove_image':'remove_mobile' }}" value="1">Remove {{ strtolower($label) }} image</label></div>@endif @endforeach</div><label class="check"><input type="checkbox" name="published" value="1" @checked($section->published)>Enable section</label><button class="button">Save {{ str_replace('_',' ',$section->kind) }} section</button></form>@if($section->published)<form method="post" action="/admin/homepage/{{ $section->id }}/remove">@csrf<button class="button button-light admin-delete" data-confirm="Remove this section from the homepage? You can enable it again later.">Remove from homepage</button></form>@endif</details>@endforeach</x-admin-layout>